rss.channel:
{{ site.name }}
{{ url_for('store.home', _external=True) }}
{{ site.tagline }}
{% for p in products %}


  {{ p.sku }}
  {{ p.name }}
  {{ p.description or p.name }}
  {{ url_for('store.product', slug=p.slug, _external=True) }}
  {% if p.image_url %}{{ absolute(p.image_url) }}{% endif %}
  {{ "in_stock" if p.stock_qty > 0 else "out_of_stock" }}
  {{ "%.2f"|format(p.price_cents / 100) }} USD
  new
  {{ site.name }}
  {{ p.sku }}
  {% if p.category_name %}{{ p.category_name }}{% endif %}

{% endfor %}
